static void zclient_flush_data ( struct thread * thread ) { struct zclient * zclient = THREAD_ARG ( thread ) ; zclient -> t_write = NULL ; switch ( buffer_flush_available ( zclient -> wb , zclient -> sock ) ) { case BUFFER_ERROR : flog_err ( EC_LIB_ZAPI_SOCKET , "%s: buffer_flush_available failed on zclient fd %d, closing" , __func__ , zclient -> sock ) ; zclient_failed ( zclient ) ; return ; case BUFFER_PENDING : zclient -> t_write = NULL ; thread_add_write ( zclient -> master , zclient_flush_data , zclient , zclient -> sock , & zclient -> t_write ) ; break ; case BUFFER_EMPTY : if ( zclient -> zebra_buffer_write_ready ) { * zclient -> zebra_buffer_write_ready ( ) ; } break ; } } 